def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    if color:
        pty = PTY()
    else:
        pty = None

    def worker():
        while True:
            args = q.get()
            if args is None:
                break
            try:
                result = subprocess.run(args, **kwargs, capture_output=True, text=True, preexec_fn=None if pty is None else os.setsid, cwd=None)
                q_out.put((result.returncode, result.stdout.encode()))
            except Exception as e:
                q_out.put((1, str(e).encode()))
            finally:
                q.task_done()

    q = queue.Queue()
    q_out = queue.Queue()

    threads = [threading.Thread(target=worker) for _ in range(target_concurrency)]
    for t in threads:
        t.start()

    for arg in varargs:
        args = list(cmd) + [arg]
        q.put(args)

    for _ in range(target_concurrency):
        q.put(None)

    q.join()

    results = []
    while not q_out.empty():
        results.append(q_out.get())

    threads = [t.join() for t in threads]

    return results

def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import os
    import re
    import subprocess

    def run_command(command: list[str], pty: bool) -> bytes:
        import pty if pty else os
        env = os.environ.copy()
        if color:
            env['TERM'] = 'xterm-256color'
        process = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env=env, preexec_fn=lambda: os.setgroups([]))
        output, _ = process.communicate(input='\n'.join(varargs).encode())
        return output

    def partition(varargs: Sequence[str], max_length: int) -> Iterator[list[str]]:
        for i in range(0, len(varargs), max_length):
            yield varargs[i:i + max_length]

    if target_concurrency == 1:
        return run_command([*cmd], color)

    varargs_partitions = list(partition(varargs, _max_length))
    processes = [subprocess.Popen([*cmd], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, preexec_fn=lambda: os.setgroups([])) for _ in range(target_concurrency)]

    for partition in varargs_partitions:
        for proc in processes:
            proc.stdin.write('\n'.join(partition).encode())
            proc.stdin.flush()

    for proc in processes:
        proc.stdin.close()

    remaining_output = b''
    for proc in processes:
        remaining_output += proc.stdout.read()

    return proc.returncode, remaining_output

