def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import traceback
    import inspect

    def format_stack(stack, max_level):
        result = []
        for frame_info in stack[::-1]:
            if not max_level or len(result) < max_level:
                result.append('  File "%s", line %d, in %s' % (frame_info.filename, frame_info.lineno, frame_info.function))
            else:
                break
        return result

    def format_path(current_id, max_path_level):
        parts = current_id.split('.')
        result = []
        for i, part in enumerate(parts):
            if not max_path_level or len(result) < max_path_level:
                result.append(part)
            else:
                result.append('...')
                break
        return '.'.join(result)

    try:
        if 'FOLIA_DEBUG' in os.environ and os.environ['FOLIA_DEBUG'] == '1':
            return str(e)
        result = []
        result.append('Exception: %s' % str(e))
        stack = []
        current_id = ''
        for frame_info, value in [(None, e.message)] + traceback.extract_tb(e.__traceback__):
            if frame_info:
                current_id = format_path(frame_info.filename.split('/')[-1].replace('.py', ''), max_path_level)
                stack.append(frame_info)
        result.append('Traceback (most recent call last):')
        result.extend(format_stack(stack, max_level))
        return '\n'.join(result)
    except Exception as ex:
        return 'Error formatting exception: %s' % str(ex)

