    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []

    # Regex patterns for keys and values
    key_pattern = re.compile(r'^[a-zA-Z0-9_]+$')
    value_pattern = re.compile(r'^[a-zA-Z0-9_]+$')

    for key, value in labels.items():
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str) and not isinstance(item, bytes):
                    errors.append({item: 'expected string or bytes-like object'})
                elif not value_pattern.match(item):
                    errors.append({item: "Label value '{}' does not match the regex".format(item)})
        elif not isinstance(value, str) and not isinstance(value, bytes):
            errors.append({value: 'expected string or bytes-like object'})
        elif key_pattern.match(key) and key_pattern.match(value):
            pass
        else:
            if not key_pattern.match(key):
                errors.append({key: "Label key '{}' does not match the regex".format(key)})
            if not value_pattern.match(value):
                errors.append({value: "Label value '{}' does not match the regex".format(value)})

    if errors:
        raise ValidationError("Validation error in labels", errors)

