def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """

    package_data = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for member in zip_ref.namelist():
                if member.endswith('.xml'):
                    basename = member.rsplit('/', 1)[-1].rsplit('.', 1)[0]
                    if basename not in package_data:
                        package_data[basename] = []
                    package_data[basename].append(zip_ref.read(member))
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {e}")
    except Exception as e:
        raise RuntimeError(f"Error exploring zip file: {e}")

    return package_data

