def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    root_inventory = self.get_inventory('root')
    if not root_inventory:
        raise ValueError("Root inventory not found")

    content_digests = {}

    for version_dir in version_dirs:
        inventory = self.get_inventory(version_dir)
        if not inventory:
            raise ValueError(f"Inventory not found for version {version_dir}")

        for file in inventory.files:
            if file.digest != root_inventory.get_file(file.name).digest:
                content_digests[file.name] = file.digest

    self.content_digests = content_digests

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = None
    version_inventories = {}

    for dir in version_dirs:
        inventory = self.get_inventory(dir)
        if not inventory:
            raise FileNotFoundError(f"Inventory not found for version {dir}")

        if not root_inventory:
            root_inventory = inventory
            continue

        for content_item in inventory.content_items:
            if content_item.digest != root_inventory.content_items[content_item.id].digest:
                self.different_digests.add(content_item.id)

        version_inventories[dir] = inventory

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = dict()
    content_digests = set()

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.txt')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version {version_dir} at {inventory_path}")

        with open(inventory_path, 'r') as file:
            for line in file:
                try:
                    content_hash, file_path = line.strip().split()
                    if version_dir == version_dirs[0]:
                        root_inventory[file_path] = content_hash
                    else:
                        content_digests.add((content_hash, file_path))
                except ValueError:
                    raise ValueError(f"Invalid inventory line in {inventory_path}: {line.strip()}")

    for file_path, expected_hash in content_digests:
        if file_path not in root_inventory or root_inventory[file_path] != expected_hash:
            raise ValueError(f"Content digest mismatch for file {file_path} at version {version_dirs[version_dirs.index(next(iter(content_digests)))]}")

    return True

