    # Parse the arguments
    ns, unparsed = parser.parse_known_args(unparsed_arguments)

    if ns.subparser_name is None:
        # If no subcommand was specified, parse as global arguments
        result = { 'global': parser.parse_args(unparsed_arguments) }
    else:
        # Otherwise, parse the arguments for the specified subcommand
