def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not Path(archive_path).exists():
        raise FileNotFoundError(f"Archive path {archive_path} does not exist")

    if not Path(tmp_path).exists():
        raise FileNotFoundError(f"Temporary path {tmp_path} does not exist")

    if not filename:
        filename = Path(archive_path).name

    temp_dir = Path(tmp_path) / filename.replace(".tar.gz", "")
    temp_dir.mkdir(parents=True, exist_ok=True)

    subprocess.run(["tar", "-xzf", archive_path, "-C", str(temp_dir)])

    return str(temp_dir)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not archive_path:
        raise ValueError("archive_path cannot be empty")

    if not Path(archive_path).exists():
        raise FileNotFoundError(f"archive'{archive_path}' not found")

    if isinstance(tmp_path, str):
        tmp_path = PosixPath(tmp_path)

    if not tmp_path.exists():
        tmp_path.mkdir(parents=True, exist_ok=True)

    if filename is None:
        filename = archive_path.split('/')[-1].split('.')[0]

    extract_path = tmp_path / filename
    try:
        if archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', extract_path], check=True)
        elif archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', extract_path], check=True)
        elif archive_path.endswith('.tar'):
            subprocess.run(['tar', '-xf', archive_path, '-C', extract_path], check=True)
        else:
            raise ValueError(f"Unsupported archive format: {archive_path}")

        return str(extract_path / filename)
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to extract archive: {e}") from e

