def subprocess_run_helper(func, *args, timeout, extra_env=None):
    try:
        import importlib.util
        spec = importlib.util.find_spec(func.__module__)
        if spec is None:
            raise ValueError(f"Module {func.__module__} is not importable")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)

        if not callable(getattr(module, func.__name__)):
            raise ValueError(f"{func.__name__} is not a callable function in module {func.__module__}")

        command = [func.__module__, func.__name__, *args]
        env = dict(os.environ)
        env.update(extra_env or {})

        result = subprocess.run(command, timeout=timeout, env=env, capture_output=True, text=True)
        return result
    except subprocess.TimeoutExpired as e:
        raise TimeoutError(f"Subprocess timed out after {timeout} seconds") from e
    except Exception as e:
        raise RuntimeError(f"Error running subprocess: {e}") from e

