def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if extra_vars is None:
        extra_vars = {}

    for key, value in extra_vars.items():
        if key in vars_dict:
            if isinstance(vars_dict[key], list) and isinstance(value, list):
                vars_dict[key].extend(value)
            elif isinstance(vars_dict[key], dict) and isinstance(value, dict):
                vars_dict[key].update(value)
            else:
                vars_dict[key] = value
        else:
            vars_dict[key] = value

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars:
        for var in extra_vars:
            if var in vars_dict:
                raise ValueError(f"Duplicate variable: {var}")
            vars_dict[var] = extra_vars[var]
    return vars_dict

