def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    type_casters = {
        'int': int,
        'float': float,
        'bool': lambda s: s.lower() in ['true', '1', 't', 'y', 'yes'],
    }

    for key, value in values_dict.items():
        if value in ['None', 'none', 'nil', 'NaN', 'True', 'False']:
            values_dict[key] = None if value.lower() in ['none', 'nil'] else value.lower() in ['true', '1', 't', 'y', 'yes']
        else:
            for converter_type, converter in type_casters.items():
                try:
                    values_dict[key] = converter(value)
                    break
                except ValueError:
                    continue

